async function loadGame(src="game.json?v=city-intel-001"){try{game=typeof src==="string"?await fetch(src).then(r=>r.json()):src;if(!game?.metadata?.id||!game.locations?.length||!game.travel||!game.dossier)throw Error("Estrutura mínima ausente.");state=JSON.parse(localStorage.getItem(`${STORE}-${game.metadata.id}`)||"null")||fresh();render()}catch(e){show("CASO INVÁLIDO","Falha ao abrir",e.message)}}
function fresh(){return{location:game.metadata.start,hours:game.metadata.total_hours,visited:[game.metadata.start],route:[game.metadata.start],evidence:[],actions:[],notes:"",warrant:false,warrantSuspect:null,finished:false,rewarded:false}}
function save(){localStorage.setItem(`${STORE}-${game.metadata.id}`,JSON.stringify(state))}function loc(id=state.location){return game.locations.find(x=>x.id===id)}function ev(id){return game.evidence.find(x=>x.id===id)}
function render(){el.title.textContent=game.metadata.title;el.briefing.textContent=game.metadata.briefing;el.code.textContent=game.metadata.code;el.notebook.value=state.notes||"";chars();career();clock();map();place();evidence();route();dossier()}
function clock(){el.time.textContent=`${Math.max(0,state.hours)}h`;el.timeBar.style.width=`${Math.max(0,state.hours)/game.metadata.total_hours*100}%`;el.time.closest(".clock-card").classList.toggle("danger",state.hours<=16)}
function map(){const allowed=new Set(game.navigation[state.location]||[]),visible=[];for(const city of game.locations)if(city.id===state.location||state.visited.includes(city.id)||allowed.has(city.id))visible.push(city);el.cities.innerHTML=visible.map(c=>{const current=c.id===state.location,visited=state.visited.includes(c.id),canGo=allowed.has(c.id),cost=canGo?game.travel[state.location][c.id]:0;return`<button class="city ${current?"current":visited?"visited":""}" style="left:${c.x}%;top:${c.y}%" data-city="${c.id}" ${current||!canGo||state.finished?"disabled":""} aria-label="${current?c.name+", posição atual":"Viajar para "+c.name+", "+cost+" horas"}"><span class="city-pulse"></span><span class="city-name">${c.name}</span><small>${current?"POSIÇÃO ATUAL":visited&&!canGo?"VISITADA":cost+"h"}</small></button>`}).join("");el.cities.querySelectorAll(".city:not(:disabled)").forEach(b=>b.onclick=()=>openTravel(b.dataset.city));const pts=state.route.map(id=>loc(id)).map(c=>`${c.x*10},${c.y*6.2}`).join(" ");el.lines.innerHTML=`<polyline points="${pts}" fill="none" stroke="#d6ff54" stroke-width="2" stroke-dasharray="7 8" vector-effect="non-scaling-stroke"/>`}
function place(){const l=loc(),info=l.city_info||{},facts=Array.isArray(info.facts)?info.facts:[];el.locTitle.textContent=l.name;el.locName.textContent=l.name;el.locType.textContent=l.type;el.locDesc.textContent=l.description;el.citySummary.textContent=info.summary||"Contexto local ainda não disponível para este caso.";let factHtml="";for(const fact of facts)factHtml+=`<li>${escape(fact)}</li>`;el.cityFacts.innerHTML=factHtml;el.coords.textContent=l.coords;el.actions.innerHTML=l.actions.map(a=>{const done=state.actions.includes(a.id),locked=a.requires_warrant&&!state.warrant;return`<button class="investigate ${done?"done":""}" data-action="${a.id}" ${done||locked||state.finished?"disabled":""}><span>${done?"✓":locked?"▣":"⌕"}</span><strong>${a.label}</strong><small>${done?"CONCLUÍDO":locked?"EXIGE MANDADO":a.arrest?"VERIFICAR IDENTIDADE · "+a.cost+"h":a.cost+"h"}</small></button>`}).join("");el.actions.querySelectorAll(".investigate:not(:disabled)").forEach(b=>b.onclick=()=>act(b.dataset.action))}
function evidence(){const found=[];for(const item of game.evidence)if(state.evidence.includes(item.id))found.push(item);el.evidenceCount.textContent=`${found.length} ${found.length===1?"catalogada":"catalogadas"}`;el.evidence.innerHTML=found.length?found.map(e=>`<article class="evidence found"><div><span>${e.id}</span><em>${e.tag}</em></div><h3>${e.title}</h3><p>${e.text}</p></article>`).join(""):'<div class="empty-state"><span>ARQUIVO LACRADO</span><strong>Nenhuma prova catalogada</strong><p>Investigue a cidade atual para revelar evidências admissíveis.</p></div>'}
function route(){const count=new Set(state.visited).size;el.visited.textContent=`${count} ${count===1?"cidade":"cidades"}`;el.route.innerHTML=state.route.map((id,i)=>`<div class="route-item"><span>${String(i+1).padStart(2,"0")}</span><i></i><strong>${loc(id).name}</strong></div>`).join("")}
function openTravel(id){pendingDestination=id;const d=loc(id),cost=game.travel[state.location][id];$("#travel-title").textContent=`Rota para ${d.name}`;$("#travel-copy").innerHTML=`O deslocamento consumirá <strong>${cost} horas</strong>. Restarão <strong>${state.hours-cost} horas</strong>.`;el.travel.showModal()}
$("#confirm-travel").onclick=()=>{const cost=game.travel[state.location][pendingDestination];spend(cost);if(state.finished)return;state.location=pendingDestination;state.route.push(pendingDestination);if(!state.visited.includes(pendingDestination))state.visited.push(pendingDestination);save();el.travel.close();render()};
function act(id){const a=loc().actions.find(x=>x.id===id);if(!spend(a.cost,a.arrest))return;state.actions.push(id);if(a.evidence&&!state.evidence.includes(a.evidence))state.evidence.push(a.evidence);save();render();if(a.arrest&&state.warrant){state.finished=true;const req=game.arrest_requirements||{minimum_evidence:0,required_evidence:[]},hasAmount=state.evidence.length>=req.minimum_evidence,hasEssentials=req.required_evidence.every(id=>state.evidence.includes(id));if(state.warrantSuspect!==game.culprit){save();render();show("MANDADO NÃO CORRESPONDENTE",game.ending.wrong_warrant_title,game.ending.wrong_warrant_text,false,true)}else if(!hasAmount||!hasEssentials){save();render();show("CONJUNTO PROBATÓRIO INSUFICIENTE",game.ending.insufficient_evidence_title,game.ending.insufficient_evidence_text,false,true)}else{awardStar();save();render();show("PRISÃO LEGALMENTE VALIDADA",game.ending.win_title,`${a.result}<br><br>${game.ending.win_text}<br><br><strong>★ Uma estrela foi adicionada à sua carreira.</strong>`,true,true)}}else show(a.evidence?`EVIDÊNCIA ${a.evidence}`:"PISTA INCONCLUSIVA",a.evidence?ev(a.evidence).title:"Tempo consumido",a.result)}
function spend(h,allowZero=false){const remaining=state.hours-h;if(remaining<0||remaining===0&&!allowZero){state.hours=0;state.finished=true;save();render();closeAll();show("PRAZO ENCERRADO",game.ending.lose_title,game.ending.lose_text,false,true);return false}state.hours=remaining;return true}
function dossier(){const f=$("#dossier-form"),evidenceLabel=state.evidence.length===1?"catalogada":"catalogadas";f.innerHTML=game.dossier.fields.map(x=>`<label><span>${x.label}</span><select name="${x.id}"><option value="">DESCONHECIDO</option>${x.options.map(o=>`<option>${o}</option>`).join("")}</select></label>`).join("")+`<div class="dossier-status"><span>BASE DE SUSPEITOS</span><strong>consulta por atributos</strong></div><div class="dossier-status"><span>PROVAS REUNIDAS</span><strong>${state.evidence.length} ${evidenceLabel}</strong></div><button class="primary wide" ${state.warrant||state.finished?"disabled":""}>${state.warrant?"MANDADO EMITIDO":"CRUZAR ATRIBUTOS"}</button>`;f.onsubmit=submitDossier;$("#dossier-button").textContent=state.warrant?"MANDADO EMITIDO ✓":"MONTAR DOSSIÊ →";$("#dossier-button").classList.toggle("issued",state.warrant)}
function submitDossier(e){e.preventDefault();const data=Object.fromEntries(new FormData(e.currentTarget)),chosen=Object.entries(data).filter(([,v])=>v);if(!chosen.length){el.dossier.close();show("DOSSIÊ VAZIO","Nenhum atributo informado","Investigue testemunhas e informe ao menos uma característica.");return}const matches=game.suspects.filter(s=>chosen.every(([k,v])=>s[k]===v));el.dossier.close();if(matches.length!==1){show("CRUZAMENTO INCONCLUSIVO",matches.length?`${matches.length} suspeitos possíveis`:"Nenhum suspeito encontrado",matches.length?matches.map(s=>s.name).join(" · "):"Revise os atributos: a combinação não existe na base.");return}state.warrant=true;state.warrantSuspect=matches[0].id;save();render();show("MANDADO APROVADO",`Mandado contra ${matches[0].name}`,"O perfil produziu uma única correspondência. Agora localize e capture o suspeito antes do prazo.")}
function career(){const stars=Number(localStorage.getItem(CAREER)||0);$("#career-stars strong").textContent=stars}function awardStar(){if(state.rewarded)return;localStorage.setItem(CAREER,String(Number(localStorage.getItem(CAREER)||0)+1));state.rewarded=true}function newCase(){closeAll();state=fresh();save();render();scrollTo({top:0,behavior:"smooth"})}
function show(k,t,c,html=false,final=false){$("#message-kicker").textContent=k;$("#message-title").textContent=t;$("#message-copy").innerHTML=html?c:escape(c);const button=el.message.querySelector(".primary.wide");button.textContent=final?"INICIAR NOVO CASO":"CONTINUAR";button.onclick=final?newCase:()=>el.message.close();el.message.showModal()}function escape(v){const d=document.createElement("div");d.textContent=String(v);return d.innerHTML}function closeAll(){document.querySelectorAll("dialog[open]").forEach(d=>d.close())}
$("#dossier-button").onclick=()=>el.dossier.showModal();$("#notes-button").onclick=()=>el.notes.showModal();document.querySelectorAll("[data-close]").forEach(b=>b.onclick=()=>document.getElementById(b.dataset.close).close());el.notebook.oninput=()=>{state.notes=el.notebook.value;chars();save()};function chars(){el.chars.textContent=`${el.notebook.value.length} caracteres`}$("#reset-button").onclick=()=>{if(confirm("Reiniciar toda a investigação?")){localStorage.removeItem(`${STORE}-${game.metadata.id}`);state=fresh();render()}};$("#json-input").onchange=async e=>{const f=e.target.files[0];if(f)await loadGame(JSON.parse(await f.text()));e.target.value=""};
async function scene(){try{const THREE=await import("https://cdn.jsdelivr.net/npm/three@0.180.0/build/three.module.js"),canvas=$("#scene"),s=new THREE.Scene(),c=new THREE.PerspectiveCamera(55,innerWidth/innerHeight,.1,100);c.position.z=6;const r=new THREE.WebGLRenderer({canvas,alpha:true,antialias:true});r.setPixelRatio(Math.min(devicePixelRatio,1.5));r.setSize(innerWidth,innerHeight);const g=new THREE.Mesh(new THREE.IcosahedronGeometry(2.8,3),new THREE.MeshBasicMaterial({color:0x4bd6c8,wireframe:true,transparent:true,opacity:.06}));g.position.x=.8;s.add(g);for(let i=0;i<80;i++){const d=new THREE.Mesh(new THREE.SphereGeometry(.008,5,5),new THREE.MeshBasicMaterial({color:0xd6ff54,transparent:true,opacity:.5}));d.position.set((Math.random()-.5)*10,(Math.random()-.5)*7,(Math.random()-.5)*3);s.add(d)}(function a(){g.rotation.y+=.0007;r.render(s,c);requestAnimationFrame(a)})();addEventListener("resize",()=>{c.aspect=innerWidth/innerHeight;c.updateProjectionMatrix();r.setSize(innerWidth,innerHeight)})}catch{}}scene();loadGame();
